"""Validate actual Rust wire matrix. Does not claim schema was generated by Rust."""
import json
from pathlib import Path
import sys
import jsonschema

root = Path(sys.argv[1])
schema = json.loads(Path(sys.argv[2]).read_text())
validator = jsonschema.Draft202012Validator(schema)
validator.check_schema(schema)
matrix = json.loads((root / 'rust-wire-matrix.json').read_text())
rows = matrix['diagnostic']
assert len(rows) == 294
for row in rows:
    validator.validate(row)
assert {r['stage'] for r in rows} == {'setup_started', 'turn_bound', 'current_error', 'terminal', 'stream_ended'}
observations = [r['observation'] for r in rows if r['stage'] == 'current_error']
assert len(observations) == 252
assert len({o['category'] for o in observations}) == 12
assert len({o['http_status_class'] for o in observations}) == 7
assert {o['notification_will_retry'] for o in observations} == {None, False, True}
assert {r['status'] for r in rows if r['stage'] == 'terminal'} == {'COMPLETED', 'FAILED', 'INTERRUPTED', 'OTHER'}
legacy = matrix['legacy_errors']
assert legacy[0] == {'message': 'dummy'}
assert legacy[1]['observation']['notification_will_retry'] is None
for row in rows:
    bad = dict(row, payload='dummy')
    assert not validator.is_valid(bad), ('unknown field', row['stage'])
    bad = {k:v for k,v in row.items() if k != 'stage'}
    assert not validator.is_valid(bad), ('missing stage', row)
print('Actual Rust wire matrix294 rows accepted;588 negative shape mutations rejected; legacy omission/null verified. Manual schema is not Rust-derived.')
